    "mail.forgotten.subject": "\"{title}\" ಅನ್ನು ಟ್ರ್ಯಾಕ್ ಮಾಡಲು ಮರೆತಿರಾ?",
    "mail.forgotten.body": "ಕಳೆದ ತಿಂಗಳು ನೀವು \"{title}\" ಅನ್ನು {count} ಟ್ರ್ಯಾಕ್ ಮಾಡಿದ್ದೀರಿ, ಆದರೆ ಕೊನೆಯದರಿಂದ {days} ದಿನಗಳಾಗಿವೆ. ನಿರಂತರತೆಯನ್ನು ಮುಂದುವರಿಸಲು ಬಯಸಿದರೆ, ಮುಂದಿನ ಬಾರಿ ಆ ಮೀಟಿಂಗ್‌ನಲ್ಲಿದ್ದಾಗ Attendance Tracker ಸೈಡ್ ಪ್ಯಾನಲ್ ತೆರೆದರೆ ಸಾಕು — ನೀವು ನಿಲ್ಲಿಸಿದ ಕಡೆಯಿಂದಲೇ ಇದು ಮುಂದುವರಿಯುತ್ತದೆ.\n\nಇಲ್ಲಿಯವರೆಗಿನ ನಿಮ್ಮ ಸರಣಿ: {link}\n\n— Derek",
    "mail.cta.seriesTrend": "ಸರಣಿಯ ಪ್ರವೃತ್ತಿ ನೋಡಿ",
    "mail.comeback.subject": "ನಿಮ್ಮ ಮುಂದಿನ ಮೀಟಿಂಗ್ ಅನ್ನು ಟ್ರ್ಯಾಕ್ ಮಾಡೋಣವೇ?",
    "mail.comeback.body": "ನೀವು \"{title}\" ಅನ್ನು ಟ್ರ್ಯಾಕ್ ಮಾಡಿ ಸುಮಾರು {days} ದಿನಗಳಾಗಿವೆ. ಮುಂದಿನ ಬಾರಿ ನೀವು ಮೀಟಿಂಗ್‌ನಲ್ಲಿದ್ದಾಗ, Attendance Tracker ಸೈಡ್ ಪ್ಯಾನಲ್ ತೆರೆದರೆ ಸಾಕು — ಯಾರು ಸೇರಿದರು, ಯಾರು ಹೊರಟರು ಮತ್ತು ಎಷ್ಟು ಹೊತ್ತು ಇದ್ದರು ಎಂಬುದನ್ನು ಇದು ದಾಖಲಿಸುತ್ತದೆ, ನಂತರ ಒಂದೇ ಕ್ಲಿಕ್‌ನಲ್ಲಿ Sheets ಗೆ ರಫ್ತು ಮಾಡುತ್ತದೆ.\n\nಒಂದು ಸಲಹೆ: ಇದು ಪುನರಾವರ್ತಿತ ತರಗತಿ ಅಥವಾ ಮೀಟಿಂಗ್ ಆಗಿದ್ದರೆ, ಅದನ್ನು ಪುನರಾವರ್ತಿತ Google Calendar ಆಹ್ವಾನದಲ್ಲಿ ಇರಿಸಿ — ಆಗ ಕೇವಲ ಒಂದು ದಿನದ್ದಲ್ಲ, ಪ್ರತಿ ಸೆಷನ್‌ನಾದ್ಯಂತ ಪ್ರತಿ ವ್ಯಕ್ತಿಯ ಹಾಜರಾತಿ ಪ್ರವೃತ್ತಿಗಳು ನಿಮಗೆ ಸಿಗುತ್ತವೆ.\n\nನಿಮ್ಮ ಇತಿಹಾಸ: {link}\n\n— Derek",
    "mail.exportGap.subject": "ನಿಮ್ಮ ಹಾಜರಾತಿ ವರದಿ ಕೇವಲ ಒಂದು ಕ್ಲಿಕ್ ದೂರದಲ್ಲಿದೆ",
    "mail.exportGap.body": "ಸುಮಾರು {days} ದಿನಗಳ ಹಿಂದೆ ನೀವು \"{title}\" ಅನ್ನು ಟ್ರ್ಯಾಕ್ ಮಾಡಿದ್ದೀರಿ, ಆದರೆ ವರದಿಯನ್ನು ಎಂದಿಗೂ ಉಳಿಸಲಿಲ್ಲ. ಮುಂದಿನ ಬಾರಿ ಆ ಮೀಟಿಂಗ್‌ನಲ್ಲಿದ್ದಾಗ, Attendance Tracker ಸೈಡ್ ಪ್ಯಾನಲ್ ತೆರೆದು ರಫ್ತು ಒತ್ತಿ — ಯಾರು ಸೇರಿದರು, ಯಾರು ಹೊರಟರು ಮತ್ತು ಎಷ್ಟು ಹೊತ್ತು ಇದ್ದರು ಎಂಬುದರೊಂದಿಗೆ ಅಚ್ಚುಕಟ್ಟಾದ Google Sheet ನಿಮಗೆ ಸಿಗುತ್ತದೆ. (ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ ಸ್ವಯಂ-ರಫ್ತು ಆನ್ ಮಾಡಿ, ಮೀಟಿಂಗ್ ಮುಗಿದಾಗ ಅದು ತಾನಾಗಿಯೇ ನಡೆಯುತ್ತದೆ.)\n\nನಿಮ್ಮ ಇತಿಹಾಸ: {link}\n\n— Derek",
